window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3ab7678c3c10c52f"]={"versions": [{"id": "FIG-3ab7678c3c10c52f", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Kommunikationsattributen für Client-Ports im Kontext des AUTOSAR-Metamodells (Package <code>Components</code> und <code>Communication</code>) und dessen Anbindung an die Verhaltensmodellierungsumgebung (<code>BM Environment</code>, aus dem Paket <code>Behavior Modeling</code>). Das Diagramm definiert die strukturelle Verankerung von Kommunikationsspezifikationen an empfangenden Port-Prototypen für Client-Server-Kommunikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Klassen, Pakete und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>Components::ComponentType</code> (Spezialisierung von <code>ARElement</code>): Bildet die Wurzel und aggregiert über die Komposition <code>+ports</code> mit der Kardinalität <code>0..*</code> Instanzen von <code>PortPrototype</code>.</li>\n<li><code>Components::PortPrototype</code>: Abstrakte Basisklasse mit den Stereotypen/Mixins <code>ExistenceDependsOnProperty</code>, <code>Identifiable</code> und <code>PropertyEvaluator</code>.</li>\n<li><code>Components::RPortPrototype</code>: Spezialisiert <code>Components::PortPrototype</code> per Generalisierung und repräsentiert einen Required Port. Aggregiert über die Komposition <code>+comSpec</code> mit der Kardinalität <code>0..*</code> Elemente vom Typ <code>Communication::RPortComSpec</code>.</li>\n<li><code>Communication::RPortComSpec</code>: Abstrakte Basisklasse für Empfangsport-Spezifikationen.</li>\n<li><code>Communication::ClientComSpec</code>: Spezialisiert <code>Communication::RPortComSpec</code> per Generalisierung. Spezifiziert Kommunikationsparameter eines Client-Ports und aggregiert über die Komposition <code>+acknowledgements</code> mit der Kardinalität <code>0..2</code> Instanzen von <code>AcknowledgementRequest</code>.</li>\n<li><code>Communication::AcknowledgementRequest</code>: Strukturiertes Kommunikationselement mit den Attributen <code>+ timeout: Float</code> und <code>+ type: Enumeration{ transmission, reception }</code>.</li>\n<li>Paket <code>BM Environment</code> (mit Vermerk <code>(from Behavior Modeling)</code>): Referenziert <code>Communication::RPortComSpec</code>, <code>Communication::ClientComSpec</code> und <code>Communication::AcknowledgementRequest</code> über gestrichelte Abhängigkeitspfeile (teilweise mit Stereotyp <code>«import»</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches UML-Klassendiagramm / Metamodellausschnitt stellt die Abbildung keine dynamischen Abläufe oder Sequenzen dar. Die Dynamik ergibt sich zur Laufzeit aus der Konfiguration: Ein auf einem <code>RPortPrototype</code> konfigurierter <code>ClientComSpec</code> steuert über zugeordnete <code>AcknowledgementRequest</code>-Instanzen das Bestätigungs- und Timeout-Verhalten bei Client-Aufrufen (Transmission- bzw. Reception-Acknowledge mit zugehörigem Timeout-Wert).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Klassendiagramm legt die metamodellkonforme Konfiguration von Client-Kommunikationsspezifikationen fest:</p>\n<ul class=\"fig-list\">\n<li>Ein <code>RPortPrototype</code> kann null bis viele <code>RPortComSpec</code>-Definitionen besitzen (<code>0..*</code>).</li>\n<li>Für einen <code>ClientComSpec</code> sind maximal zwei <code>AcknowledgementRequest</code>-Instanzen zulässig (<code>0..2</code>), entsprechend den beiden Ausprägungen des Aufzählungstyps (<code>transmission</code>, <code>reception</code>).</li>\n<li>Entwickler und Generatoren von Verhaltensmodellen müssen bei aktivierten Bestätigungen für jeden Request-Typ die jeweiligen Timeout-Parameter (<code>Float</code>) spezifizieren und die Import-Beziehungen der Verhaltensmodellierungsumgebung (<code>BM Environment</code>) berücksichtigen.</li>\n</ul>"}, {"id": "FIG-30122f6bf80eee84", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Kommunikationsattributen für Client-Ports im Kontext des AUTOSAR-Metamodells (Package <code>Components</code> und <code>Communication</code>) und dessen Anbindung an die Verhaltensmodellierungsumgebung (<code>BM Environment</code>, aus dem Paket <code>Behavior Modeling</code>). Das Diagramm definiert die strukturelle Verankerung von Kommunikationsspezifikationen an empfangenden Port-Prototypen für Client-Server-Kommunikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Klassen, Pakete und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>Components::ComponentType</code> (Spezialisierung von <code>ARElement</code>): Bildet die Wurzel und aggregiert über die Komposition <code>+ports</code> mit der Kardinalität <code>0..*</code> Instanzen von <code>PortPrototype</code>.</li>\n<li><code>Components::PortPrototype</code>: Abstrakte Basisklasse mit den Stereotypen/Mixins <code>ExistenceDependsOnProperty</code>, <code>Identifiable</code> und <code>PropertyEvaluator</code>.</li>\n<li><code>Components::RPortPrototype</code>: Spezialisiert <code>Components::PortPrototype</code> per Generalisierung und repräsentiert einen Required Port. Aggregiert über die Komposition <code>+comSpec</code> mit der Kardinalität <code>0..*</code> Elemente vom Typ <code>Communication::RPortComSpec</code>.</li>\n<li><code>Communication::RPortComSpec</code>: Abstrakte Basisklasse für Empfangsport-Spezifikationen.</li>\n<li><code>Communication::ClientComSpec</code>: Spezialisiert <code>Communication::RPortComSpec</code> per Generalisierung. Spezifiziert Kommunikationsparameter eines Client-Ports und aggregiert über die Komposition <code>+acknowledgements</code> mit der Kardinalität <code>0..2</code> Instanzen von <code>AcknowledgementRequest</code>.</li>\n<li><code>Communication::AcknowledgementRequest</code>: Strukturiertes Kommunikationselement mit den Attributen <code>+ timeout: Float</code> und <code>+ type: Enumeration{ transmission, reception }</code>.</li>\n<li>Paket <code>BM Environment</code> (mit Vermerk <code>(from Behavior Modeling)</code>): Referenziert <code>Communication::RPortComSpec</code>, <code>Communication::ClientComSpec</code> und <code>Communication::AcknowledgementRequest</code> über gestrichelte Abhängigkeitspfeile (teilweise mit Stereotyp <code>«import»</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches UML-Klassendiagramm / Metamodellausschnitt stellt die Abbildung keine dynamischen Abläufe oder Sequenzen dar. Die Dynamik ergibt sich zur Laufzeit aus der Konfiguration: Ein auf einem <code>RPortPrototype</code> konfigurierter <code>ClientComSpec</code> steuert über zugeordnete <code>AcknowledgementRequest</code>-Instanzen das Bestätigungs- und Timeout-Verhalten bei Client-Aufrufen (Transmission- bzw. Reception-Acknowledge mit zugehörigem Timeout-Wert).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Klassendiagramm legt die metamodellkonforme Konfiguration von Client-Kommunikationsspezifikationen fest:</p>\n<ul class=\"fig-list\">\n<li>Ein <code>RPortPrototype</code> kann null bis viele <code>RPortComSpec</code>-Definitionen besitzen (<code>0..*</code>).</li>\n<li>Für einen <code>ClientComSpec</code> sind maximal zwei <code>AcknowledgementRequest</code>-Instanzen zulässig (<code>0..2</code>), entsprechend den beiden Ausprägungen des Aufzählungstyps (<code>transmission</code>, <code>reception</code>).</li>\n<li>Entwickler und Generatoren von Verhaltensmodellen müssen bei aktivierten Bestätigungen für jeden Request-Typ die jeweiligen Timeout-Parameter (<code>Float</code>) spezifizieren und die Import-Beziehungen der Verhaltensmodellierungsumgebung (<code>BM Environment</code>) berücksichtigen.</li>\n</ul>"}], "trans": [{"from": "FIG-3ab7678c3c10c52f", "to": "FIG-30122f6bf80eee84", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
